--
-- Table structure for table `doctor_consultation`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doctor_consultation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `patient_id` int NOT NULL COMMENT '患者用户ID',
  `doctor_id` int NOT NULL COMMENT '医生ID',
  `title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '咨询主题',
  `status` tinyint(1) DEFAULT '0' COMMENT '状态(0:进行中,1:已结束)',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '最后更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_patient` (`patient_id`) USING BTREE,
  KEY `idx_doctor` (`doctor_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=549839276 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='医患会话表';
/*!40101 SET character_set_client = @saved_cs_client */;

