/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `doctor_message` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `consultation_id` int NOT NULL COMMENT '关联会话ID',
  `sender_id` int NOT NULL COMMENT '发送者ID',
  `receiver_id` int NOT NULL COMMENT '接收者ID',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '消息内容',
  `message_type` tinyint(1) DEFAULT '0' COMMENT '消息类型(0:文本,1:图片,2:健康数据)',
  `health_data_id` int DEFAULT NULL COMMENT '关联健康数据ID',
  `is_read` tinyint(1) DEFAULT '0' COMMENT '是否已读(0:未读,1:已读)',
  `create_time` datetime DEFAULT NULL COMMENT '发送时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_consultation` (`consultation_id`) USING BTREE,
  KEY `idx_sender` (`sender_id`) USING BTREE,
  KEY `idx_receiver` (`receiver_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1925570588 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='医患聊天消息表';
/*!40101 SET character_set_client = @saved_cs_client */;

