  `sex_male` tinyint NOT NULL DEFAULT '0' COMMENT '1男0女',
  `bmi` decimal(6,2) NOT NULL,
  `heart_disease` tinyint NOT NULL DEFAULT '0' COMMENT '冠心病/心肌梗死相关病史',
