  `drinking_any` tinyint NOT NULL DEFAULT '0' COMMENT '是否饮酒',
  `drinks_per_week` decimal(8,2) NOT NULL DEFAULT '0.00' COMMENT '每周饮酒量',
  `physical_activity` tinyint NOT NULL DEFAULT '0' COMMENT '是否有休闲身体活动',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_elder_risk_profile_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=416 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='老人风险评估基础档案';
