CREATE TABLE `elder_vital_measurement` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `systolic_pressure` decimal(8,2) DEFAULT NULL COMMENT '收缩压',
  `diastolic_pressure` decimal(8,2) DEFAULT NULL COMMENT '舒张压',
  `heart_rate` decimal(8,2) DEFAULT NULL COMMENT '心率',
  `spo2` decimal(8,2) DEFAULT NULL COMMENT '血氧',
  `temperature` decimal(8,2) DEFAULT NULL COMMENT '体温',
  `respiratory_rate` decimal(8,2) DEFAULT NULL COMMENT '呼吸频率',
  `supplemental_oxygen` tinyint DEFAULT NULL COMMENT '本次是否吸氧',
  `consciousness` varchar(24) DEFAULT NULL COMMENT '本次意识状态或新发意识改变',
  `measured_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_elder_vital_user_time` (`user_id`,`measured_at`)
) ENGINE=InnoDB AUTO_INCREMENT=491 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='老人连续生命体征记录，用于个人历史校准';
