-- Table structure for table `personalized_risk_assessment`
--

/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `personalized_risk_assessment` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `group_risk_probability` decimal(8,6) NOT NULL COMMENT '五项指标模型预警值，列名为兼容旧记录保留',
  `personal_change_score` decimal(8,6) NOT NULL DEFAULT '0.000000' COMMENT '个人历史变化程度',
  `baseline_available` tinyint NOT NULL DEFAULT '0' COMMENT '个人基线是否可用',
  `risk_level` varchar(20) NOT NULL COMMENT '正常/关注/高风险',
  `reasons_json` text COMMENT '主要原因JSON',
  `single_alerts_json` text COMMENT '实测单项警报JSON',
  `news2_complete` tinyint NOT NULL DEFAULT '0' COMMENT '本次五项数值指标是否完整',
  `assessment_basis` varchar(32) NOT NULL DEFAULT 'LEGACY' COMMENT '评估依据',
  `model_name` varchar(64) DEFAULT NULL,
  `model_version` varchar(64) DEFAULT NULL,
  `assessment_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `request_id` varchar(36) DEFAULT NULL,
  `input_snapshot_json` longtext,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_personal_assessment_request` (`user_id`,`request_id`),
  KEY `idx_personalized_risk_user_time` (`user_id`,`assessment_time`)
) ENGINE=InnoDB AUTO_INCREMENT=490 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='个性化健康风险评估结果';
/*!40101 SET character_set_client = @saved_cs_client */;

